package com.beatoflove.standardcalculator;
import android.app.*;import android.content.*;import android.widget.*;import org.json.*;import java.math.*;import java.util.*;
final class CurrencyPanel extends ResponsiveForm {
 static final String[] CURRENCIES={"USD","THB","EUR","JPY","GBP","CNY","SGD","AUD","CHF","HKD","MYR","CAD","NZD","KRW","INR","IDR","PHP","VND","TWD","AED","SAR","SEK","NOK","DKK"};
 final SharedPreferences prefs; int generation; boolean active; Runnable resumeFetch;
 CurrencyPanel(Activity a){super(a);prefs=a.getSharedPreferences("currency53",0);}
 void stop(){active=false;generation++;} void resume(){active=true;if(resumeFetch!=null)resumeFetch.run();}
 void attach(LinearLayout p){active=true;resumeFetch=null;LinearLayout l=screen(p,"","");LinearLayout modes=adaptivePair(l,300);LinearLayout b=col();l.addView(b);TextView[] tabs=new TextView[2];String[] names={"Convert","Exchange Rates"};for(int i=0;i<2;i++){final int n=i;tabs[i]=formButton(names[i],()->showMode(n,b,tabs),false);pairChild(modes,tabs[i]);}showMode(0,b,tabs);}
 void showMode(int n,LinearLayout b,TextView[] tabs){generation++;resumeFetch=null;for(int i=0;i<tabs.length;i++){tabs[i].setBackground(bg(i==n?BLUE:KEY));tabs[i].setTextColor(i==n?BG:WHITE);}b.removeAllViews();if(n==0)convert(b);else exchangeRates(b);}
 String s(Spinner sp){return String.valueOf(sp.getSelectedItem());}
 void convert(LinearLayout l){Spinner source=spin(l,"Rate source",new String[]{"Daily reference (Frankfurter)","Latest Forex quote (cached)"});LinearLayout units=adaptivePair(l,280);LinearLayout fromBox=col(),toBox=col();pairChild(units,fromBox);pairChild(units,toBox);Spinner from=spin(fromBox,"From",CURRENCIES),to=spin(toBox,"To",CURRENCIES);to.setSelection(1);EditText amount=input(l,"Amount","1",false);CalcActions.Log log=new CalcActions.Log(a,"currency");
 java.util.function.Supplier<String> context=()->amount.getText()+" "+s(from)+" → "+s(to)+" · "+source.getSelectedItem();
 LinearLayout resultArea=col();l.addView(resultArea);TextView out=result(resultArea);resultArea.removeView(out);
 CalcActions.add(a,resultArea,()->log.copyRecord(context.get(),out.getText().toString()),()->log.show("Currency · History"));resultArea.addView(out);
 CalcActions.AutoRecord auto=new CalcActions.AutoRecord(out,log,context);
 TextView status=compactText("",12,MUTE,false);l.addView(status);final BigDecimal[] rate={null};final String[] pair={""};final int[] seq={0};Runnable calc=()->{try{if(rate[0]==null||!pair[0].equals(s(from)+"/"+s(to))){out.setText("—");return;}out.setText(FinancialMath.dec(amount.getText().toString()).multiply(rate[0],FinancialMath.MC).setScale(4,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString()+" "+s(to));}catch(Exception e){out.setText("—");}finally{auto.changed();}};Runnable fetch=()->{if(!active)return;final String src=s(from),dst=s(to),key=src+"/"+dst;final int g=generation, id=++seq[0];pair[0]=key;rate[0]=null;if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}if(source.getSelectedItemPosition()==1){try{SharedPreferences quotes=a.getSharedPreferences("live_markets53",0);String raw=quotes.getString("q:"+key,"");boolean inverse=raw.isEmpty();if(inverse)raw=quotes.getString("q:"+dst+"/"+src,"");JSONObject q=new JSONObject(raw);BigDecimal r=new BigDecimal(q.getString("p"));long stamp=q.getLong("t");if(r.signum()<=0||stamp<=0)throw new Exception();rate[0]=inverse?BigDecimal.ONE.divide(r,MathContext.DECIMAL128):r;status.setText("Cached "+q.optString("source","Twelve Data")+" quote · "+new Date(stamp)+" · not live / not bank rate");}catch(Exception e){status.setText("No cached Forex quote for this pair. Open Markets → Forex first.");}calc.run();return;}String cache=prefs.getString("ref:"+key,"");try{JSONObject j=new JSONObject(cache);rate[0]=new BigDecimal(j.getString("rate"));status.setText("Cached reference · "+j.getString("date"));}catch(Exception ex){status.setText("Fetching daily reference…");}calc.run();if(src.equals(dst)){rate[0]=BigDecimal.ONE;status.setText("Same currency");calc.run();return;}PriceService.reference(src,dst,(j,err)->{if(!active||g!=generation||id!=seq[0])return;if(j==null){status.setText((rate[0]==null?"Unavailable":"Cached reference")+" · "+err);return;}try{BigDecimal r=new BigDecimal(j.getString("rate"));String date=j.getString("date");if(r.signum()<=0||!src.equals(j.getString("base"))||!dst.equals(j.getString("quote")))throw new Exception();java.time.LocalDate parsed=java.time.LocalDate.parse(date);if(parsed.isAfter(java.time.LocalDate.now().plusDays(1)))throw new Exception();if(rate[0]!=null&&!cache.isEmpty()){try{String old=new JSONObject(cache).getString("date");if(parsed.isBefore(java.time.LocalDate.parse(old))){status.setText("Cached reference · newer than provider response · "+old);return;}}catch(org.json.JSONException ignored){}}rate[0]=r;prefs.edit().putString("ref:"+key,j.toString()).apply();status.setText("Frankfurter · daily reference · "+date+"\n1 "+src+" = "+r+" "+dst);calc.run();}catch(Exception ex){status.setText("Invalid response · not updated");}});};resumeFetch=fetch;selected(source,fetch);selected(from,fetch);selected(to,fetch);watch(amount,calc);LinearLayout actions=adaptivePair(l,340);pairChild(actions,formButton("⇅ Swap currencies",()->{int i=from.getSelectedItemPosition();from.setSelection(to.getSelectedItemPosition());to.setSelection(i);},false));pairChild(actions,formButton("Refresh rate",fetch,true));l.addView(compactText("Reference / cached quote · not a live bank rate.",12,MUTE,false));}
 void exchangeRates(LinearLayout l){
  l.addView(text("THB per 1 foreign currency unit",13,MUTE,false));
  final String[] quotes=Arrays.stream(CURRENCIES).filter(c->!c.equals("THB")).toArray(String[]::new);
  LinearLayout rows=col();l.addView(rows);TextView status=text("",12,MUTE,false);l.addView(status);
  Map<String,ReferenceRate> rates=new LinkedHashMap<>();Set<String> fresh=new HashSet<>();final int[] request={0};final long[] last={-60000};final boolean[] inFlight={false};
  Runnable render=()->{rows.removeAllViews();rateRow(rows,"Currency","THB / unit","Date",true);for(String cc:quotes){ReferenceRate r=rates.get(cc);if(r==null){rateRow(rows,cc,"—","—",false);continue;}rateRow(rows,cc,r.thb(),r.date+(fresh.contains(cc)?"":" · cache"),false);}};
  for(String cc:quotes){try{JSONObject old=new JSONObject(prefs.getString("boardref:THB/"+cc,""));ReferenceRate r=decode(old,cc);rates.put(cc,r);}catch(Exception ignored){}}
  Runnable fetch=()->{if(!active||inFlight[0])return;long now=android.os.SystemClock.elapsedRealtime();if(now-last[0]<10000){return;}last[0]=now;inFlight[0]=true;final int g=generation,id=++request[0];fresh.clear();render.run();status.setText("Checking reference rates…");PriceService.referenceBoard("THB",quotes,(data,err)->{if(!active||g!=generation||id!=request[0])return;inFlight[0]=false;if(data==null){status.setText((rates.isEmpty()?"Unavailable":"Cached reference")+" · "+err);return;}Set<String> allowed=new HashSet<>(Arrays.asList(quotes));for(int i=0;i<data.length();i++){try{JSONObject o=data.getJSONObject(i);String cc=o.getString("quote");if(!allowed.contains(cc))continue;ReferenceRate r=decode(o,cc);ReferenceRate old=rates.get(cc);if(old!=null&&r.date.compareTo(old.date)<0)continue;rates.put(cc,r);fresh.add(cc);prefs.edit().putString("boardref:THB/"+cc,o.toString()).apply();}catch(Exception ignored){}}render.run();status.setText(fresh.isEmpty()?"No valid new reference rows":("Frankfurter · daily reference · "+fresh.size()+" / "+quotes.length+" updated"));});};
  // Reset a request invalidated by Activity pause; stale callbacks cannot update the UI.
  resumeFetch=()->{inFlight[0]=false;last[0]=-60000;fetch.run();};action(l,"Refresh Exchange Rates",fetch);l.addView(text("Reference only · not bank BUY/SELL or live Forex. Date is the publisher's rate date. Cached rows are marked separately.",12,MUTE,false));render.run();fetch.run();
 }
 static ReferenceRate decode(JSONObject o,String cc)throws Exception{return ReferenceRate.parse(o.getString("base"),o.getString("quote"),cc,o.getString("date"),o.getString("rate"),java.time.LocalDate.now(java.time.ZoneId.of("Asia/Bangkok")));}
 void rateRow(LinearLayout l,String a1,String a2,String a3,boolean header){LinearLayout r=row();r.setBackground(bg(header?FUNC:CARD));String[] v={a1,a2,a3};float[] weights={.8f,1.25f,1.2f};for(int i=0;i<3;i++){TextView t=text(v[i],header?12:i==2?11:14,i==0?WHITE:i==1?BLUE:MUTE,header);t.setGravity(i==0?android.view.Gravity.START:android.view.Gravity.END);r.addView(t,new LinearLayout.LayoutParams(0,-2,weights[i]));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(2),0,dp(2));l.addView(r,p);}
}
